-- LIVE SUPABASE SCHEMA — INDEXES\n\nCREATE UNIQUE INDEX customers_email_unique ON public."Customers" USING btree (lower(btrim("Email"))) WHERE (NULLIF(btrim("Email"), ''::text) IS NOT NULL);\nCREATE UNIQUE INDEX customers_phone_unique ON public."Customers" USING btree (regexp_replace(btrim("Teléfono"), '\D'::text, ''::text, 'g'::text)) WHERE (NULLIF(regexp_replace(btrim("Teléfono"), '\D'::text, ''::text, 'g'::text), ''::text) IS NOT NULL);\nCREATE INDEX customers_name_idx ON public."Customers" USING btree (lower(btrim("Name")));\nCREATE INDEX customers_created_at_idx ON public."Customers" USING btree (created_at);\nCREATE INDEX idx_business_expenses_date ON public.business_expenses USING btree (expense_date DESC);\nCREATE INDEX idx_business_expenses_category ON public.business_expenses USING btree (category);\nCREATE INDEX business_expenses_date_category_idx ON public.business_expenses USING btree (expense_date DESC, category);\nCREATE INDEX cash_movements_reference_purchase_id_idx ON public.cash_movements USING btree (reference_purchase_id);\nCREATE INDEX cash_movements_parent_movement_id_idx ON public.cash_movements USING btree (parent_movement_id);\nCREATE UNIQUE INDEX cash_registers_only_one_open_idx ON public.cash_registers USING btree (status) WHERE (status = 'open'::text);\nCREATE UNIQUE INDEX cash_registers_one_open_per_day ON public.cash_registers USING btree (register_date) WHERE (status = 'open'::text);\nCREATE UNIQUE INDEX cost_settings_code_key ON public.cost_settings USING btree (code);\nCREATE UNIQUE INDEX doordash_order_details_order_id_key ON public.doordash_order_details USING btree (order_id);\nCREATE INDEX idx_inventory_movements_ingredient_id ON public.inventory_movements USING btree (ingredient_id);\nCREATE INDEX idx_inventory_movements_created_at ON public.inventory_movements USING btree (created_at DESC);\nCREATE INDEX inventory_movements_ingredient_created_idx ON public.inventory_movements USING btree (ingredient_id, created_at DESC);\nCREA