e_active_per_item_size ON public.recipes USING btree (item_id, size_id) WHERE (active = true);\nCREATE INDEX recipes_item_id_idx ON public.recipes USING btree (item_id);\nCREATE INDEX recipes_size_id_idx ON public.recipes USING btree (size_id);\nCREATE UNIQUE INDEX sales_goals_month_unique ON public.sales_goals USING btree (goal_month);\nCREATE UNIQUE INDEX stamp_transactions_order_id_unique ON public.stamp_transactions USING btree (order_id) WHERE (order_id IS NOT NULL);\nCREATE UNIQUE INDEX tax_rates_code_key ON public.tax_rates USING btree (code);